const express = require('express');
const { InfluxDB } = require('@influxdata/influxdb-client');
const knex = require('knex')({ client: 'pg', connection: process.env.DATABASE_URL });

const app = express();
app.use(express.json());

const client = new InfluxDB({ url: process.env.INFLUX_URL, token: process.env.INFLUX_ADMIN_TOKEN });

app.delete('/api/telemetry/measurements/purge', async (req, res) => {
  const { deviceId, start, stop } = req.body;
  if (!deviceId) {
    return res.status(400).json({ error: 'Missing deviceId parameter' });
  }

  // Ensure the device belongs to the authenticated tenant
  const device = await knex('registered_devices')
    .where({ id: deviceId, tenant_id: req.user.tenantId })
    .first();
  if (!device) {
    return res.status(404).json({ error: 'Device not found in tenant inventory' });
  }

  const deleteApi = client.getDeleteApi(process.env.INFLUX_ORG);
  try {
    await deleteApi.postDelete({
      org: process.env.INFLUX_ORG,
      bucket: 'iot_devices',
      body: {
        start: start || '1970-01-01T00:00:00Z',
        stop: stop || new Date().toISOString(),
        predicate: `_measurement="sensor_readings" AND device_id="${deviceId}"`
      }
    });

    return res.json({ status: 'Data purged successfully', deviceId });
  } catch (err) {
    return res.status(500).json({ error: 'Influx delete operation failed' });
  }
});

module.exports = app;
